-- Phase 3B: no source deletion, only durable revocation and derived validity.
CREATE TABLE media_scope_invalidations (
 scope_id TEXT PRIMARY KEY,
 generation INTEGER NOT NULL,
 cutoff_at TEXT NOT NULL,
 last_deletion_id TEXT NOT NULL
);
CREATE TABLE media_reconciliations (
 deletion_id TEXT PRIMARY KEY REFERENCES media_deletions(deletion_id),
 initial_plan_id TEXT NOT NULL REFERENCES media_deletion_plans(plan_id),
 plan_id TEXT NOT NULL REFERENCES media_deletion_plans(plan_id),
 status TEXT NOT NULL CHECK(status IN ('running','failed','reconciled')),
 step_index INTEGER NOT NULL DEFAULT 0,
 retry_count INTEGER NOT NULL DEFAULT 0,
 error TEXT NOT NULL DEFAULT '',
 workset_json TEXT NOT NULL,
 plan_history_json TEXT NOT NULL,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL
);
CREATE TABLE media_reconciliation_steps (
 deletion_id TEXT NOT NULL REFERENCES media_reconciliations(deletion_id),
 step TEXT NOT NULL,
 result_json TEXT NOT NULL,
 completed_at TEXT NOT NULL,
 PRIMARY KEY(deletion_id,step)
);
CREATE TABLE media_object_states (
 object_table TEXT NOT NULL,
 object_key TEXT NOT NULL,
 scope_id TEXT,
 validity TEXT NOT NULL CHECK(validity IN ('valid','needs_review','invalid','revoked')),
 summary_valid INTEGER NOT NULL DEFAULT 0,
 generation INTEGER NOT NULL,
 reason TEXT NOT NULL,
 metrics_json TEXT NOT NULL DEFAULT '{}',
 last_deletion_id TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 PRIMARY KEY(object_table,object_key)
);
CREATE INDEX idx_media_object_scope ON media_object_states(scope_id,validity);
CREATE TABLE media_evidence_revocations (
 deletion_id TEXT NOT NULL REFERENCES media_deletions(deletion_id),
 object_table TEXT NOT NULL,
 object_key TEXT NOT NULL,
 field TEXT NOT NULL,
 evidence_kind TEXT NOT NULL,
 evidence_id TEXT NOT NULL,
 original_json TEXT NOT NULL,
 plan_id TEXT NOT NULL REFERENCES media_deletion_plans(plan_id),
 created_at TEXT NOT NULL,
 PRIMARY KEY(deletion_id,object_table,object_key,field,evidence_kind,evidence_id)
);
CREATE TRIGGER media_revocation_immutable_update BEFORE UPDATE ON media_evidence_revocations BEGIN SELECT RAISE(ABORT,'immutable_evidence_revocation'); END;
CREATE TRIGGER media_revocation_immutable_delete BEFORE DELETE ON media_evidence_revocations BEGIN SELECT RAISE(ABORT,'immutable_evidence_revocation'); END;
