CREATE TRIGGER media_review_lock_memory_rotation_sequences_delete BEFORE DELETE ON memory_rotation_sequences WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='memory_rotation_sequences' AND ms.object_key=json_object('sequence_id',OLD.sequence_id) AND (1=1)) AND media_reconcile_allowed()=0 BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_state_internal_insert BEFORE INSERT ON media_object_states WHEN media_reconcile_allowed()=0 BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_state_internal_update BEFORE UPDATE ON media_object_states WHEN media_reconcile_allowed()=0 BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_state_internal_delete BEFORE DELETE ON media_object_states WHEN media_reconcile_allowed()=0 BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
DROP VIEW IF EXISTS readable_entity_mentions;
CREATE VIEW readable_entity_mentions AS SELECT r.* FROM entity_mentions r JOIN readable_observations o ON o.id=r.observation_id WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='entity_mentions' AND ms.object_key=json_object('id',r.id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_entity_observations;
CREATE VIEW readable_entity_observations AS SELECT r.* FROM entity_observations r JOIN readable_observations o ON o.id=r.observation_id WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='entity_observations' AND ms.object_key=json_object('entity_id',r.entity_id,'observation_id',r.observation_id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_event_observations;
CREATE VIEW readable_event_observations AS SELECT r.* FROM event_observations r JOIN readable_observations o ON o.id=r.observation_id WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='event_observations' AND ms.object_key=json_object('event_id',r.event_id,'observation_id',r.observation_id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_event_participants;
CREATE VIEW readable_event_participants AS SELECT r.id,r.event_id,r.person_id,r.role,r.confidence,r.revision,r.created_at,r.updated_at,(SELECT COALESCE(json_group_array(j.value),'[]') FROM json_each(r.evidence_ids_json) j WHERE j.type='text' AND j.value IN (SELECT id FROM readable_observations)) AS evidence_ids_json FROM event_participants r WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='event_participants' AND ms.object_key=json_object('id',r.id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_event_entities;
CREATE VIEW readable_event_entities AS SELECT r.event_id,r.entity_id,r.relation,r.confidence,r.created_at,r.updated_at,(SELECT COALESCE(json_group_array(j.value),'[]') FROM json_each(r.evidence_ids_json) j WHERE j.type='text' AND j.value IN (SELECT id FROM readable_observations)) AS evidence_ids_json FROM event_entities r WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='event_entities' AND ms.object_key=json_object('entity_id',r.entity_id,'event_id',r.event_id,'relation',r.relation) AND (validity!='valid'));
DROP VIEW readable_facts;
CREATE VIEW readable_facts AS SELECT x.* FROM facts x WHERE NOT EXISTS (
 SELECT 1 FROM json_each(x.evidence_ids_json) j JOIN media_tombstones t ON t.kind=CASE WHEN j.type='object' THEN json_extract(j.value,'$.kind') ELSE 'observation' END AND t.object_id=CASE WHEN j.type='object' THEN json_extract(j.value,'$.id') ELSE j.value END) AND NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='facts' AND ms.object_key=json_object('id',x.id) AND (validity!='valid'));
DROP VIEW readable_relationships;
CREATE VIEW readable_relationships AS SELECT x.* FROM relationships x WHERE NOT EXISTS (
 SELECT 1 FROM json_each(x.evidence_ids_json) j JOIN media_tombstones t ON t.kind=CASE WHEN j.type='object' THEN json_extract(j.value,'$.kind') ELSE 'observation' END AND t.object_id=CASE WHEN j.type='object' THEN json_extract(j.value,'$.id') ELSE j.value END) AND NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='relationships' AND ms.object_key=json_object('id',x.id) AND (validity!='valid'));
DROP VIEW readable_entity_properties;
CREATE VIEW readable_entity_properties AS SELECT x.* FROM entity_properties x WHERE NOT EXISTS (
 SELECT 1 FROM json_each(x.evidence_ids_json) j JOIN media_tombstones t ON t.kind=CASE WHEN j.type='object' THEN json_extract(j.value,'$.kind') ELSE 'observation' END AND t.object_id=CASE WHEN j.type='object' THEN json_extract(j.value,'$.id') ELSE j.value END) AND NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='entity_properties' AND ms.object_key=json_object('id',x.id) AND (validity!='valid'));
DROP VIEW readable_semantic_claims;
CREATE VIEW readable_semantic_claims AS SELECT x.* FROM semantic_claims x WHERE NOT EXISTS (
 SELECT 1 FROM json_each(x.evidence_ids_json) j JOIN media_tombstones t ON t.kind=CASE WHEN j.type='object' THEN json_extract(j.value,'$.kind') ELSE 'observation' END AND t.object_id=CASE WHEN j.type='object' THEN json_extract(j.value,'$.id') ELSE j.value END) AND NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='semantic_claims' AND ms.object_key=json_object('id',x.id) AND (validity!='valid'));
DROP VIEW readable_semantic_profiles;
CREATE VIEW readable_semantic_profiles AS SELECT x.* FROM semantic_profiles x WHERE NOT EXISTS (
 SELECT 1 FROM json_each(x.evidence_ids_json) j JOIN media_tombstones t ON t.kind=CASE WHEN j.type='object' THEN json_extract(j.value,'$.kind') ELSE 'observation' END AND t.object_id=CASE WHEN j.type='object' THEN json_extract(j.value,'$.id') ELSE j.value END) AND NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='semantic_profiles' AND ms.object_key=json_object('id',x.id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_entities;
CREATE VIEW readable_entities AS SELECT e.id,e.scope_id,e.entity_type,e.canonical_name,e.status,e.family_role,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='entities' AND ms.object_key=json_object('id',e.id) AND (summary_valid=0)) THEN '' ELSE e.summary END AS summary,e.confidence,e.identity_state,e.role_state,e.name_state,e.created_at,e.updated_at FROM entities e WHERE 1=1;
DROP VIEW IF EXISTS readable_events;
CREATE VIEW readable_events AS SELECT e.id,e.scope_id,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',e.id) AND (summary_valid=0)) THEN '待更新事件' ELSE e.title END AS title,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',e.id) AND (summary_valid=0)) THEN '' ELSE e.event_type END AS event_type,e.time_start,e.time_end,e.place,e.admin_district,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',e.id) AND (summary_valid=0)) THEN '' ELSE e.activity END AS activity,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',e.id) AND (summary_valid=0)) THEN '' ELSE e.summary END AS summary,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',e.id) AND (summary_valid=0)) THEN 0 ELSE e.confidence END AS confidence,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',e.id) AND (summary_valid=0)) THEN 0 ELSE e.aggregation_score END AS aggregation_score,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',e.id) AND (summary_valid=0)) THEN '{}' ELSE e.aggregation_breakdown_json END AS aggregation_breakdown_json,e.status,e.revision,e.created_at,e.updated_at,e.source_type,e.source_asset_id,e.source_scene_index,e.source_start_sec,e.source_end_sec,e.source_metadata_json FROM events e WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',e.id) AND (validity!='valid')) AND NOT EXISTS (SELECT 1 FROM media_tombstones t WHERE (t.kind='event' AND t.object_id=e.id) OR (t.kind='asset' AND t.object_id=e.source_asset_id)) AND NOT EXISTS (SELECT 1 FROM event_observations eo JOIN media_tombstones t ON t.kind='observation' AND t.object_id=eo.observation_id WHERE eo.event_id=e.id AND NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='event_observations' AND ms.object_key=json_object('event_id',eo.event_id,'observation_id',eo.observation_id) AND (validity='revoked')));
DROP VIEW IF EXISTS readable_person_portrait_revisions;
CREATE VIEW readable_person_portrait_revisions AS SELECT p.* FROM person_portrait_revisions p WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='person_portrait_revisions' AND ms.object_key=json_object('id',p.id) AND (validity!='valid')) AND NOT EXISTS (SELECT 1 FROM entity_mentions m JOIN observations o ON o.id=m.observation_id JOIN assets a ON a.id=o.asset_id WHERE m.entity_id=p.person_id AND a.deletion_state!='active');
DROP VIEW IF EXISTS readable_family_person_portraits;
CREATE VIEW readable_family_person_portraits AS SELECT r.* FROM family_person_portraits r WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='family_person_portraits' AND ms.object_key=json_object('id',r.id) AND (validity!='valid')) AND NOT EXISTS (SELECT 1 FROM json_each(r.evidence_refs_json) j JOIN media_tombstones t ON t.kind='observation' AND t.object_id=j.value WHERE j.type='text');
DROP VIEW IF EXISTS readable_family_relationships;
CREATE VIEW readable_family_relationships AS SELECT r.* FROM family_relationships r WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='family_relationships' AND ms.object_key=json_object('id',r.id) AND (validity!='valid')) AND NOT EXISTS (SELECT 1 FROM json_each(r.evidence_refs_json) j JOIN media_tombstones t ON t.kind='observation' AND t.object_id=j.value WHERE j.type='text');
DROP VIEW IF EXISTS readable_family_person_memberships;
CREATE VIEW readable_family_person_memberships AS SELECT r.* FROM family_person_memberships r WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='family_person_memberships' AND ms.object_key=json_object('id',r.id) AND (validity!='valid')) AND NOT EXISTS (SELECT 1 FROM json_each(r.evidence_refs_json) j JOIN media_tombstones t ON t.kind='observation' AND t.object_id=j.value WHERE j.type='text');
DROP VIEW IF EXISTS readable_face_prototypes;
CREATE VIEW readable_face_prototypes AS SELECT p.* FROM face_prototypes p JOIN readable_face_instances f ON f.id=p.face_instance_id WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='face_prototypes' AND ms.object_key=json_object('id',p.id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_person_moments;
CREATE VIEW readable_person_moments AS SELECT r.* FROM person_moments r JOIN readable_assets a ON a.id=r.asset_id JOIN readable_events e ON e.id=r.event_id WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='person_moments' AND ms.object_key=json_object('id',r.id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_person_appearance_evidence;
CREATE VIEW readable_person_appearance_evidence AS SELECT r.* FROM person_appearance_evidence r JOIN readable_assets a ON a.id=r.asset_id WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='person_appearance_evidence' AND ms.object_key=json_object('id',r.id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_memory_graph_nodes;
CREATE VIEW readable_memory_graph_nodes AS SELECT r.* FROM memory_graph_nodes r WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='memory_graph_nodes' AND ms.object_key=json_object('id',r.id) AND (validity!='valid')) AND NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='memory_graph_builds' AND ms.object_key=json_object('scope_id',r.scope_id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_memory_graph_edges;
CREATE VIEW readable_memory_graph_edges AS SELECT r.* FROM memory_graph_edges r WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='memory_graph_edges' AND ms.object_key=json_object('id',r.id) AND (validity!='valid')) AND NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='memory_graph_builds' AND ms.object_key=json_object('scope_id',r.scope_id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_memory_graph_builds;
CREATE VIEW readable_memory_graph_builds AS SELECT r.* FROM memory_graph_builds r WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='memory_graph_builds' AND ms.object_key=json_object('scope_id',r.scope_id) AND (validity!='valid')) AND NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='memory_graph_builds' AND ms.object_key=json_object('scope_id',r.scope_id) AND (validity!='valid'));
DROP VIEW IF EXISTS readable_memory_rotation_sequences;
CREATE VIEW readable_memory_rotation_sequences AS SELECT r.* FROM memory_rotation_sequences r WHERE NOT EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='memory_rotation_sequences' AND ms.object_key=json_object('sequence_id',r.sequence_id) AND (validity!='valid'));
DROP VIEW readable_memory_vectors;
CREATE VIEW readable_memory_vectors AS SELECT v.* FROM memory_vectors v WHERE NOT EXISTS (
 SELECT 1 FROM media_tombstones t WHERE (t.kind=v.source_type AND t.object_id=v.source_id)
 OR (t.kind='asset' AND t.object_id=json_extract(v.metadata_json,'$.asset_id'))
 OR (t.kind='observation' AND t.object_id=json_extract(v.metadata_json,'$.observation_id')))
 AND NOT (v.source_type='event' AND EXISTS (SELECT 1 FROM events WHERE id=v.source_id) AND NOT EXISTS (SELECT 1 FROM readable_events WHERE id=v.source_id)) AND NOT (v.source_type='event' AND EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',v.source_id) AND (summary_valid=0 OR validity!='valid')));
DROP VIEW readable_text_vectors;
CREATE VIEW readable_text_vectors AS SELECT v.* FROM text_vectors v WHERE NOT EXISTS (
 SELECT 1 FROM media_tombstones t WHERE (t.kind=v.source_type AND t.object_id=v.source_id)
 OR (t.kind='asset' AND t.object_id=json_extract(v.metadata_json,'$.asset_id'))
 OR (t.kind='observation' AND t.object_id=json_extract(v.metadata_json,'$.observation_id')))
 AND NOT (v.source_type='event' AND EXISTS (SELECT 1 FROM events WHERE id=v.source_id) AND NOT EXISTS (SELECT 1 FROM readable_events WHERE id=v.source_id)) AND NOT (v.source_type='event' AND EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='events' AND ms.object_key=json_object('id',v.source_id) AND (summary_valid=0 OR validity!='valid')));
DROP VIEW IF EXISTS readable_face_clusters;
CREATE VIEW readable_face_clusters AS SELECT r.id,r.scope_id,r.status,r.entity_id,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='face_clusters' AND ms.object_key=json_object('id',r.id) AND (validity!='valid')) THEN '[]' ELSE r.representative_embedding_json END AS representative_embedding_json,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='face_clusters' AND ms.object_key=json_object('id',r.id) AND (1=1)) THEN (SELECT COUNT(*) FROM readable_face_instances f WHERE f.cluster_id=r.id) ELSE r.member_count END AS member_count,CASE WHEN EXISTS (SELECT 1 FROM media_object_states ms WHERE ms.object_table='face_clusters' AND ms.object_key=json_object('id',r.id) AND (validity!='valid')) THEN 0 ELSE r.confidence END AS confidence,r.revision,r.created_at,r.updated_at FROM face_clusters r WHERE 1=1;
DROP VIEW IF EXISTS readable_agent_conversation_messages;
CREATE VIEW readable_agent_conversation_messages AS SELECT m.rowid AS rowid,m.id,m.conversation_id,m.scope_id,m.turn_id,m.role,CASE WHEN m.role IN ('assistant','tool') AND EXISTS (SELECT 1 FROM media_scope_invalidations si LEFT JOIN agent_turns t ON t.id=m.turn_id WHERE si.scope_id=m.scope_id AND julianday(COALESCE(t.created_at,m.created_at))<=julianday(si.cutoff_at)) THEN '（素材证据已变更，该历史输出不再作为有效证据）' ELSE m.content END AS content,m.created_at FROM agent_conversation_messages m WHERE 1=1;
DROP VIEW IF EXISTS readable_agent_turns;
CREATE VIEW readable_agent_turns AS SELECT r.rowid AS rowid,r.id,r.conversation_id,r.scope_id,r.question,r.status,r.termination_reason,CASE WHEN EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=r.scope_id AND julianday(r.created_at)<=julianday(si.cutoff_at)) THEN '素材证据已变更，该历史输出不再作为有效证据' ELSE r.answer END AS answer,r.attachments_json,r.requirements_json,r.created_at,r.updated_at,CASE WHEN EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=r.scope_id AND julianday(r.created_at)<=julianday(si.cutoff_at)) THEN '[]' ELSE r.candidates_json END AS candidates_json,CASE WHEN EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=r.scope_id AND julianday(r.created_at)<=julianday(si.cutoff_at)) THEN '[]' ELSE r.trace_json END AS trace_json,r.idempotency_key,r.execution_state,r.attempt_no,r.lease_expires_at,r.fence,r.waiting_reason,r.next_retry_at,r.cancel_requested,r.failure_count FROM agent_turns r WHERE 1=1;
DROP VIEW IF EXISTS readable_agent_turn_events_v2;
CREATE VIEW readable_agent_turn_events_v2 AS SELECT r.* FROM agent_turn_events_v2 r JOIN agent_turns t ON t.id=r.turn_id WHERE NOT EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=t.scope_id AND julianday(t.created_at)<=julianday(si.cutoff_at));
DROP VIEW IF EXISTS readable_agent_result_sets;
CREATE VIEW readable_agent_result_sets AS SELECT r.rowid AS rowid,r.* FROM agent_result_sets r WHERE NOT EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=r.scope_id AND julianday(COALESCE((SELECT t.created_at FROM agent_turns t WHERE t.id=r.turn_id),r.created_at))<=julianday(si.cutoff_at));
CREATE TRIGGER media_scope_model_lock_facts_insert BEFORE INSERT ON facts WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) AND NOT (0) BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_facts_update BEFORE UPDATE ON facts WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) AND NOT (0) BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_relationships_insert BEFORE INSERT ON relationships WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) AND NOT (0) BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_relationships_update BEFORE UPDATE ON relationships WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) AND NOT (0) BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_semantic_claims_insert BEFORE INSERT ON semantic_claims WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) AND NOT (NEW.confidence_source IN ('user','manual','user_override','user-confirmed','user_confirmed') AND json_valid(NEW.evidence_ids_json) AND NEW.evidence_ids_json='[]' AND NEW.supporting_event_ids_json='[]') BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_semantic_claims_update BEFORE UPDATE ON semantic_claims WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) AND NOT (NEW.confidence_source IN ('user','manual','user_override','user-confirmed','user_confirmed') AND json_valid(NEW.evidence_ids_json) AND NEW.evidence_ids_json='[]' AND NEW.supporting_event_ids_json='[]') BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_entity_properties_insert BEFORE INSERT ON entity_properties WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=(SELECT scope_id FROM entities WHERE id=NEW.entity_id)) AND NOT (NEW.source IN ('user','manual','user_override','user-confirmed','user_confirmed') AND json_valid(NEW.evidence_ids_json) AND NEW.evidence_ids_json='[]') BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_entity_properties_update BEFORE UPDATE ON entity_properties WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=(SELECT scope_id FROM entities WHERE id=NEW.entity_id)) AND NOT (NEW.source IN ('user','manual','user_override','user-confirmed','user_confirmed') AND json_valid(NEW.evidence_ids_json) AND NEW.evidence_ids_json='[]') BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_events_insert BEFORE INSERT ON events WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) AND NOT (0) BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_events_update BEFORE UPDATE ON events WHEN media_reconcile_allowed()=0 AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) AND NOT (0) BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_entities_insert BEFORE INSERT ON entities WHEN media_reconcile_allowed()=0 AND NEW.summary!='' AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_scope_model_lock_entities_update BEFORE UPDATE OF summary,confidence ON entities WHEN media_reconcile_allowed()=0 AND NEW.summary!='' AND EXISTS (SELECT 1 FROM media_scope_invalidations si WHERE si.scope_id=NEW.scope_id) BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
